#!/usr/bin/env bash
#
# fix-treasury-A3-csv-export.sh   (Item A, Phase A3)
#
# WHAT: Adds per-recipient CSV export to the payroll dashboard.
#   API  nexum-api/src/routes/payroll.ts
#        + GET /payroll/recipients/export?wallet=&from=&to=  (bulk per-recipient
#          rows across a wallet's batches in a date range, JOINed to batch name +
#          chain; named columns only). Inserted before 'export default router'.
#   WEB  nexum-web/hooks/usePayroll.ts
#        + PayrollExportRow type + fetchPayrollExport() one-shot fetch (appended).
#   WEB  nexum-web/app/(app)/treasury/TreasuryContent.tsx
#        + "Export CSV" header button + downloadCSV() (CSV-safe quoting, USDC==USD
#          1:1). FULL-FILE replace of the A2 dashboard.
#
# WHY:  Completes the "exportable" promise in the dashboard subtitle; payroll CSV
#       is the recipient ledger accountants need.
#
# SCOPE: API + web. 1 anchored insert (payroll.ts), 1 anchored append
#        (usePayroll.ts), 1 full-file SHA-verified replace (TreasuryContent.tsx).
#        Precondition: A2 applied (TreasuryContent == A2 SHA). Guard warns if not.
#
# DELIVERY: v2 - each payload base64, decoded+verified before use; anchored
#           edits assert single match; backup-once per file; idempotent (markers);
#           --revert restores all three from newest backups.
#
# USAGE:
#   bash fix-treasury-A3-csv-export.sh          # apply
#   bash fix-treasury-A3-csv-export.sh --revert # restore newest backups
#
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$REPO_ROOT"

API_FILE="nexum-api/src/routes/payroll.ts"
HOOK_FILE="nexum-web/hooks/usePayroll.ts"
TREAS_FILE="nexum-web/app/(app)/treasury/TreasuryContent.tsx"
STAMP="$(date +%Y%m%d-%H%M%S)"
TREAS_SHA="5b4bde9aafe100564e307693df5a69e8a2a11e9349d98168d857b486b36a745a"
A2_SHA="4599b5dbef3fa7906830a51a1deac1f54e241beb1610a580b14c815573b2e56b"
FILES=("$API_FILE" "$HOOK_FILE" "$TREAS_FILE")

# ----- revert -----
if [ "${1:-}" = "--revert" ]; then
  rc=0
  for f in "${FILES[@]}"; do
    newest="$(ls -1t "$f".bak.* 2>/dev/null | head -1 || true)"
    if [ -n "$newest" ]; then cp "$newest" "$f"; echo "reverted $f from $newest"
    else echo "revert: no backup for $f"; rc=1; fi
  done
  exit $rc
fi

for f in "${FILES[@]}"; do [ -f "$f" ] || { echo "ABORT: $f not found" >&2; exit 1; }; done

# ----- idempotency: all three already applied? -----
if grep -qF "recipients/export" "$API_FILE" \
   && grep -qF "fetchPayrollExport" "$HOOK_FILE" \
   && grep -qF "Export CSV" "$TREAS_FILE"; then
  echo "already applied: A3 present in all three files - nothing to do"
  exit 0
fi

# ----- decode payloads to temp + verify -----
TMPDIR="$(mktemp -d)"; trap 'rm -rf "$TMPDIR"' EXIT
printf '%s' ""  | base64 -d > "$TMPDIR/api_snippet.txt"
printf '%s' "" | base64 -d > "$TMPDIR/hook_append.txt"
printf '%s' "" | base64 -d > "$TMPDIR/treasury.tsx"

[ -s "$TMPDIR/api_snippet.txt" ]  || { echo "ABORT: api payload empty" >&2; exit 1; }
[ -s "$TMPDIR/hook_append.txt" ]  || { echo "ABORT: hook payload empty" >&2; exit 1; }
GOT_TREAS="$(sha256sum "$TMPDIR/treasury.tsx" | awk '{print $1}')"
if [ "$GOT_TREAS" != "$TREAS_SHA" ]; then
  echo "ABORT: TreasuryContent payload SHA mismatch ($GOT_TREAS != $TREAS_SHA). No files touched." >&2
  exit 1
fi

# ----- warn if TreasuryContent base is not A2 -----
CUR_TREAS="$(sha256sum "$TREAS_FILE" | awk '{print $1}')"
if [ "$CUR_TREAS" != "$A2_SHA" ] && [ "$CUR_TREAS" != "$TREAS_SHA" ]; then
  echo "WARN: $TREAS_FILE is not the A2 base (SHA $CUR_TREAS). Backing up and replacing anyway." >&2
fi

# ----- 1) API: insert route before 'export default router' (anchored) -----
if ! grep -qF "recipients/export" "$API_FILE"; then
  cp "$API_FILE" "$API_FILE.bak.$STAMP"
  python3 - "$API_FILE" "$TMPDIR/api_snippet.txt" <<'PY'
import sys
path, snip_path = sys.argv[1], sys.argv[2]
s = open(path, encoding="utf-8").read()
snip = open(snip_path, encoding="utf-8").read()
anchor = "export default router"
if s.count(anchor) != 1:
    sys.stderr.write(f"ABORT: {path} anchor 'export default router' count {s.count(anchor)}\n"); sys.exit(1)
s = s.replace(anchor, snip + anchor)
open(path, "w", encoding="utf-8").write(s)
print("api route inserted")
PY
fi

# ----- 2) HOOK: append (anchored on absence) -----
if ! grep -qF "fetchPayrollExport" "$HOOK_FILE"; then
  cp "$HOOK_FILE" "$HOOK_FILE.bak.$STAMP"
  # trim trailing whitespace/newlines then append delta (keeps single separation)
  python3 - "$HOOK_FILE" "$TMPDIR/hook_append.txt" <<'PY'
import sys
path, add_path = sys.argv[1], sys.argv[2]
s = open(path, encoding="utf-8").read().rstrip()
add = open(add_path, encoding="utf-8").read()
open(path, "w", encoding="utf-8").write(s + add)
print("hook appended")
PY
fi

# ----- 3) TREASURY: full-file replace (SHA-verified above) -----
if [ "$CUR_TREAS" != "$TREAS_SHA" ]; then
  cp "$TREAS_FILE" "$TREAS_FILE.bak.$STAMP"
  cp "$TMPDIR/treasury.tsx" "$TREAS_FILE"
  echo "TreasuryContent replaced with A3"
fi

echo ""
echo "OK: A3 applied (API route + export hook + Export CSV button)"
echo ""
echo "Done. Standard deploy (BOTH packages):"
echo "  cd ~/AfriFX/nexum-api && npx tsc --noEmit && npm run build"
echo "  cd ~/AfriFX/nexum-web && rm -rf .next && npx tsc --noEmit && npm run build"
echo "  cd ~/AfriFX && git add -A && git commit -m 'feat: payroll per-recipient CSV export (A3)' && git push"
